import { useEffect, useState } from 'react';
import { 
  Package, 
  Truck, 
  AlertTriangle, 
  CheckCircle,
  Activity,
  TrendingUp,
  Clock,
  FileText,
  RefreshCw,
} from 'lucide-react';
import { useUIStore, useNotificationStore } from '../../store';
import { dashboardApi } from '../../api';
import KPICard from '../../components/ui/KPICard';
import StatusBadge from '../../components/ui/StatusBadge';
import DataTable from '../../components/ui/DataTable';
import { SkeletonCard, SkeletonChart, SkeletonTable } from '../../components/common/Skeleton';
import { 
  LineChart, 
  Line, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  AreaChart,
  Area,
} from 'recharts';

const Dashboard = () => {
  const { setPageTitle, setBreadcrumbs } = useUIStore();
  const { error: showError } = useNotificationStore();

  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [data, setData] = useState({
    kpis: null,
    chartData: null,
    alerts: [],
    recentShipments: [],
    activityLog: [],
  });

  useEffect(() => {
    setPageTitle('Dashboard');
    setBreadcrumbs(['Home', 'Dashboard']);
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const response = await dashboardApi.getOverview();
      if (response.success) {
        setData(response.data);
      }
    } catch (err) {
      showError(err.message || 'Failed to load dashboard data');
      // Set fallback data for UI display
      setData({
        kpis: {
          totalInventory: { value: '2.4M', change: '+12.5%', changeType: 'positive' },
          activeShipments: { value: '847', change: '+8.3%', changeType: 'positive' },
          pendingApprovals: { value: '23', change: '-15%', changeType: 'positive' },
          complianceRate: { value: '99.7%', change: '+0.3%', changeType: 'positive' },
        },
        chartData: {
          supplyTrend: [
            { name: 'Jan', value: 4000 },
            { name: 'Feb', value: 3000 },
            { name: 'Mar', value: 5000 },
            { name: 'Apr', value: 4500 },
            { name: 'May', value: 6000 },
            { name: 'Jun', value: 5500 },
          ],
          distribution: [
            { name: 'Vaccines', value: 35, color: '#00C2A8' },
            { name: 'Antibiotics', value: 25, color: '#3B82F6' },
            { name: 'Analgesics', value: 20, color: '#F59E0B' },
            { name: 'Others', value: 20, color: '#64748B' },
          ],
        },
        alerts: [
          { id: 1, type: 'warning', message: 'Low stock alert: Amoxicillin 500mg', time: '5 min ago', facility: 'Cairo Central' },
          { id: 2, type: 'critical', message: 'Temperature excursion detected', time: '12 min ago', facility: 'Alexandria Hub' },
          { id: 3, type: 'info', message: 'Shipment #SH-2847 delivered', time: '28 min ago', facility: 'Giza Warehouse' },
          { id: 4, type: 'warning', message: 'Expiry alert: Batch #BT-9823', time: '45 min ago', facility: 'Luxor Facility' },
        ],
        recentShipments: [
          { id: 'SH-2851', origin: 'Cairo Central', destination: 'Alexandria Hub', status: 'in_transit', eta: '2h 30m' },
          { id: 'SH-2850', origin: 'Giza Warehouse', destination: 'Aswan Facility', status: 'pending', eta: '4h 15m' },
          { id: 'SH-2849', origin: 'Alexandria Hub', destination: 'Port Said', status: 'delivered', eta: '-' },
          { id: 'SH-2848', origin: 'Cairo Central', destination: 'Luxor Facility', status: 'in_transit', eta: '6h 45m' },
        ],
        activityLog: [
          { id: 1, user: 'Dr. Ahmed Hassan', action: 'Approved shipment #SH-2847', time: '10 min ago' },
          { id: 2, user: 'System', action: 'Auto-generated compliance report', time: '25 min ago' },
          { id: 3, user: 'Inspector Karim', action: 'Completed facility inspection', time: '1 hour ago' },
          { id: 4, user: 'Admin Fatima', action: 'Updated inventory records', time: '2 hours ago' },
        ],
      });
    } finally {
      setLoading(false);
    }
  };

  const handleRefresh = async () => {
    setRefreshing(true);
    await fetchDashboardData();
    setRefreshing(false);
  };

  const shipmentColumns = [
    { key: 'id', label: 'Shipment ID', width: '120px' },
    { key: 'origin', label: 'Origin' },
    { key: 'destination', label: 'Destination' },
    { 
      key: 'status', 
      label: 'Status',
      render: (value) => <StatusBadge status={value} size="sm" />
    },
    { key: 'eta', label: 'ETA', align: 'right' },
  ];

  const getAlertIcon = (type) => {
    switch (type) {
      case 'critical':
        return <AlertTriangle size={16} style={{ color: 'var(--accent-danger)' }} />;
      case 'warning':
        return <AlertTriangle size={16} style={{ color: 'var(--accent-warning)' }} />;
      case 'info':
        return <CheckCircle size={16} style={{ color: 'var(--accent-info)' }} />;
      default:
        return <Activity size={16} style={{ color: 'var(--text-muted)' }} />;
    }
  };

  return (
    <div className="animate-fadeIn">
      {/* Header */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          marginBottom: 'var(--spacing-lg)',
        }}
      >
        <div>
          <h1
            style={{
              fontSize: 'var(--font-size-2xl)',
              fontWeight: 700,
              color: 'var(--text-primary)',
              marginBottom: 'var(--spacing-xs)',
            }}
          >
            National Supply Chain Overview
          </h1>
          <p style={{ fontSize: 'var(--font-size-sm)', color: 'var(--text-muted)' }}>
            Real-time pharmaceutical supply chain monitoring and control
          </p>
        </div>
        <button
          onClick={handleRefresh}
          disabled={refreshing}
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 'var(--spacing-sm)',
            padding: 'var(--spacing-sm) var(--spacing-md)',
            backgroundColor: 'var(--bg-card)',
            border: '1px solid var(--border-primary)',
            borderRadius: 'var(--radius-md)',
            color: 'var(--text-secondary)',
            cursor: refreshing ? 'not-allowed' : 'pointer',
            fontSize: 'var(--font-size-sm)',
          }}
        >
          <RefreshCw size={16} className={refreshing ? 'animate-spin' : ''} />
          Refresh
        </button>
      </div>

      {/* KPI Cards */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))',
          gap: 'var(--spacing-md)',
          marginBottom: 'var(--spacing-lg)',
        }}
      >
        {loading ? (
          <>
            <SkeletonCard />
            <SkeletonCard />
            <SkeletonCard />
            <SkeletonCard />
          </>
        ) : (
          <>
            <KPICard
              title="Total Inventory"
              value={data.kpis?.totalInventory?.value || '-'}
              change={data.kpis?.totalInventory?.change}
              changeType={data.kpis?.totalInventory?.changeType}
              icon={Package}
              subtitle="units nationwide"
            />
            <KPICard
              title="Active Shipments"
              value={data.kpis?.activeShipments?.value || '-'}
              change={data.kpis?.activeShipments?.change}
              changeType={data.kpis?.activeShipments?.changeType}
              icon={Truck}
              subtitle="in transit"
            />
            <KPICard
              title="Pending Approvals"
              value={data.kpis?.pendingApprovals?.value || '-'}
              change={data.kpis?.pendingApprovals?.change}
              changeType={data.kpis?.pendingApprovals?.changeType}
              icon={Clock}
              subtitle="awaiting review"
            />
            <KPICard
              title="Compliance Rate"
              value={data.kpis?.complianceRate?.value || '-'}
              change={data.kpis?.complianceRate?.change}
              changeType={data.kpis?.complianceRate?.changeType}
              icon={CheckCircle}
              subtitle="this month"
            />
          </>
        )}
      </div>

      {/* Charts Row */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: '2fr 1fr',
          gap: 'var(--spacing-md)',
          marginBottom: 'var(--spacing-lg)',
        }}
      >
        {/* Supply Trend Chart */}
        {loading ? (
          <SkeletonChart />
        ) : (
          <div
            style={{
              padding: 'var(--spacing-lg)',
              backgroundColor: 'var(--bg-card)',
              borderRadius: 'var(--radius-lg)',
              border: '1px solid var(--border-primary)',
            }}
          >
            <h3
              style={{
                fontSize: 'var(--font-size-base)',
                fontWeight: 600,
                color: 'var(--text-primary)',
                marginBottom: 'var(--spacing-lg)',
              }}
            >
              Supply Chain Volume Trend
            </h3>
            <ResponsiveContainer width="100%" height={240}>
              <AreaChart data={data.chartData?.supplyTrend || []}>
                <defs>
                  <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#00C2A8" stopOpacity={0.3} />
                    <stop offset="95%" stopColor="#00C2A8" stopOpacity={0} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="var(--border-primary)" />
                <XAxis 
                  dataKey="name" 
                  stroke="var(--text-muted)" 
                  tick={{ fill: 'var(--text-muted)', fontSize: 12 }}
                />
                <YAxis 
                  stroke="var(--text-muted)" 
                  tick={{ fill: 'var(--text-muted)', fontSize: 12 }}
                />
                <Tooltip
                  contentStyle={{
                    backgroundColor: 'var(--bg-card)',
                    border: '1px solid var(--border-primary)',
                    borderRadius: 'var(--radius-md)',
                    color: 'var(--text-primary)',
                  }}
                />
                <Area
                  type="monotone"
                  dataKey="value"
                  stroke="#00C2A8"
                  strokeWidth={2}
                  fillOpacity={1}
                  fill="url(#colorValue)"
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        )}

        {/* Distribution Pie Chart */}
        {loading ? (
          <SkeletonChart />
        ) : (
          <div
            style={{
              padding: 'var(--spacing-lg)',
              backgroundColor: 'var(--bg-card)',
              borderRadius: 'var(--radius-lg)',
              border: '1px solid var(--border-primary)',
            }}
          >
            <h3
              style={{
                fontSize: 'var(--font-size-base)',
                fontWeight: 600,
                color: 'var(--text-primary)',
                marginBottom: 'var(--spacing-lg)',
              }}
            >
              Inventory Distribution
            </h3>
            <ResponsiveContainer width="100%" height={180}>
              <PieChart>
                <Pie
                  data={data.chartData?.distribution || []}
                  cx="50%"
                  cy="50%"
                  innerRadius={50}
                  outerRadius={70}
                  paddingAngle={4}
                  dataKey="value"
                >
                  {(data.chartData?.distribution || []).map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip
                  contentStyle={{
                    backgroundColor: 'var(--bg-card)',
                    border: '1px solid var(--border-primary)',
                    borderRadius: 'var(--radius-md)',
                    color: 'var(--text-primary)',
                  }}
                />
              </PieChart>
            </ResponsiveContainer>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--spacing-md)', marginTop: 'var(--spacing-md)' }}>
              {(data.chartData?.distribution || []).map((item, index) => (
                <div key={index} style={{ display: 'flex', alignItems: 'center', gap: 'var(--spacing-xs)' }}>
                  <div
                    style={{
                      width: '10px',
                      height: '10px',
                      borderRadius: 'var(--radius-sm)',
                      backgroundColor: item.color,
                    }}
                  />
                  <span style={{ fontSize: 'var(--font-size-xs)', color: 'var(--text-secondary)' }}>
                    {item.name} ({item.value}%)
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Alerts & Shipments Row */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: '1fr 2fr',
          gap: 'var(--spacing-md)',
          marginBottom: 'var(--spacing-lg)',
        }}
      >
        {/* Live Alerts */}
        <div
          style={{
            padding: 'var(--spacing-lg)',
            backgroundColor: 'var(--bg-card)',
            borderRadius: 'var(--radius-lg)',
            border: '1px solid var(--border-primary)',
          }}
        >
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              marginBottom: 'var(--spacing-md)',
            }}
          >
            <h3
              style={{
                fontSize: 'var(--font-size-base)',
                fontWeight: 600,
                color: 'var(--text-primary)',
              }}
            >
              Live Alerts
            </h3>
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 'var(--spacing-xs)',
              }}
            >
              <div className="status-indicator status-online" />
              <span style={{ fontSize: 'var(--font-size-xs)', color: 'var(--text-muted)' }}>
                Real-time
              </span>
            </div>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--spacing-sm)' }}>
            {loading ? (
              Array.from({ length: 4 }).map((_, i) => (
                <div key={i} className="skeleton" style={{ height: '60px', borderRadius: 'var(--radius-md)' }} />
              ))
            ) : (
              (data.alerts || []).map((alert) => (
                <div
                  key={alert.id}
                  style={{
                    display: 'flex',
                    gap: 'var(--spacing-md)',
                    padding: 'var(--spacing-md)',
                    backgroundColor: 'var(--bg-secondary)',
                    borderRadius: 'var(--radius-md)',
                    borderLeft: `3px solid ${
                      alert.type === 'critical' ? 'var(--accent-danger)' :
                      alert.type === 'warning' ? 'var(--accent-warning)' :
                      'var(--accent-info)'
                    }`,
                  }}
                >
                  {getAlertIcon(alert.type)}
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div
                      style={{
                        fontSize: 'var(--font-size-sm)',
                        color: 'var(--text-primary)',
                        marginBottom: '2px',
                      }}
                      className="truncate"
                    >
                      {alert.message}
                    </div>
                    <div
                      style={{
                        fontSize: 'var(--font-size-xs)',
                        color: 'var(--text-muted)',
                      }}
                    >
                      {alert.facility} • {alert.time}
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Recent Shipments Table */}
        <div
          style={{
            backgroundColor: 'var(--bg-card)',
            borderRadius: 'var(--radius-lg)',
            border: '1px solid var(--border-primary)',
            overflow: 'hidden',
          }}
        >
          <div
            style={{
              padding: 'var(--spacing-lg)',
              borderBottom: '1px solid var(--border-primary)',
            }}
          >
            <h3
              style={{
                fontSize: 'var(--font-size-base)',
                fontWeight: 600,
                color: 'var(--text-primary)',
              }}
            >
              Recent Shipments
            </h3>
          </div>
          <DataTable
            columns={shipmentColumns}
            data={data.recentShipments || []}
            loading={loading}
            pagination={false}
            searchable={false}
          />
        </div>
      </div>

      {/* Activity Log */}
      <div
        style={{
          padding: 'var(--spacing-lg)',
          backgroundColor: 'var(--bg-card)',
          borderRadius: 'var(--radius-lg)',
          border: '1px solid var(--border-primary)',
        }}
      >
        <h3
          style={{
            fontSize: 'var(--font-size-base)',
            fontWeight: 600,
            color: 'var(--text-primary)',
            marginBottom: 'var(--spacing-md)',
          }}
        >
          Recent Activity
        </h3>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--spacing-sm)' }}>
          {loading ? (
            Array.from({ length: 4 }).map((_, i) => (
              <div key={i} className="skeleton" style={{ height: '48px', borderRadius: 'var(--radius-md)' }} />
            ))
          ) : (
            (data.activityLog || []).map((activity) => (
              <div
                key={activity.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  padding: 'var(--spacing-md)',
                  backgroundColor: 'var(--bg-secondary)',
                  borderRadius: 'var(--radius-md)',
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--spacing-md)' }}>
                  <div
                    style={{
                      width: '32px',
                      height: '32px',
                      borderRadius: 'var(--radius-full)',
                      backgroundColor: 'var(--accent-secondary)',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      fontSize: 'var(--font-size-sm)',
                      fontWeight: 600,
                      color: 'var(--text-primary)',
                    }}
                  >
                    {activity.user.charAt(0)}
                  </div>
                  <div>
                    <div style={{ fontSize: 'var(--font-size-sm)', color: 'var(--text-primary)' }}>
                      <span style={{ fontWeight: 500 }}>{activity.user}</span>
                      <span style={{ color: 'var(--text-secondary)' }}> {activity.action}</span>
                    </div>
                  </div>
                </div>
                <span style={{ fontSize: 'var(--font-size-xs)', color: 'var(--text-muted)' }}>
                  {activity.time}
                </span>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
